export default [{"id":400,"question":"أنا أعمل في الدفاع المدني، وأحيانًا يشبّ حريقٌ، فتبدأ العملية من وقت صلاة المغرب، فأنشغل حتى أذان العشاء، فهل يجوز لي في هذه الحالة أن أجمع بين الصَّلاتين؟","title":"حكم جمع الصلاة لرجال إطفاء الحرائق","answer":"الجواب: نعم، هذا من أعظم الحاجات، إذا وُجد الحريق فإنَّك تبدأ بالحريق، ولو أخَّرت المغرب إلى العشاء، ولو أخَّرت الظهر إلى العصر، ولو أخَّرت العصر إلى غروب الشمس، حتى ولو فات الوقتُ؛ لأن هذا مهمٌّ يفوت، وخطره عظيم، والنبي ﷺ أخَّر صلاة العصر حتى غابت الشمس يوم الأحزاب لما اشتدَّ القتالُ، فصلاها بعد المغرب عليه الصلاة والسلام.\nفالمقصود أنه إذا كان هناك خطرُ الحريق، أو خطرُ الهدم، أو ما أشبهه من الأمور العظيمة التي يُخشى أن يفوت الأمرُ ولا تُتلافى؛ فإنه يُبدأ بها لدفع خطرها، وإن أخَّر الصلاة، وإن جمعها إلى ما بعدها.","link":"https://binbaz.org.sa/fatwas/4796/حكم-جمع-الصلاة-لرجال-اطفاء-الحراىق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/fatawa_dross0457.mp3","categories":["أحكام الجمع"]},{"id":814,"question":"السؤال الأول يقول: ما القول الفصل في مسألة قصر الصلاة في منى بالنسبة لأهل مكة؟ وما سبب هذا القصر؟ نرجو توضيح ذلك أثابكم الله.","title":"حكم قصر الصلاة في مِنى لأهل مكة","answer":"الجواب: القول الصواب في ذلك: أن أهل مكة إذا حجُّوا مع الناس يقصرون ويجمعون؛ لأن الرسول ﷺ لما حجَّ بالناس حجَّة الوداع قصر في منى، وفي عرفات، وفي مُزدلفة، ولم يمنع أهلَ مكة، ولم يقل لهم: يا أهل مكة، أتموا، أو: لا تجمعوا، هذا هو القول الراجح.\nوالعلماء في هذا مختلفون: منهم مَن يقول: لهم الجمع دون القصر، ومنهم مَن يقول: لا جمع لهم ولا قصر؛ لأنَّهم قريبون من المشاعر، وليس بينهم وبين المشاعر سفرٌ، ولكن الصواب أنهم يقصرون ويجمعون مع الناس، يقصرون في منى من دون جمعٍ، هذا هو السنة والأفضل، وفي عرفات يقصرون ويجمعون، وفي مزدلفة كذلك.\nأما العلة: فقال جماعةٌ: إنها النُّسُك، أن العلة النُّسك، وقال جماعةٌ: إنها السفر، ولكن التعليل بالسَّفر لا يتمشَّى على رأي الجمهور؛ لأن الجمهور يرون المسافة يومًا وليلةً، وليس بين مكة وبين المشاعر إلا الشيء اليسير.\nفالصواب أن نقول: علينا أن نتبع السنةَ ونأخذ بها، أما العلَّة فإلى الله، سواء كانت العلةُ النُّسك، أو غير ذلك، العلة والحكمة لا نعلمها، الله أعلم، فعلينا أن نتمسَّك بما دلَّ عليه شرعنا، وما دلَّت عليه سنة نبينا، ويكفينا هذا، أما العلة والحكمة فالله أعلم؛ لأنَّ القول بأنه من أجل النُّسك محل نظرٍ، والقول بأنه من أجل السَّفر محل نظرٍ، ولكن علينا أن نفعل ما أقرَّه نبينا ﷺ من كونه أقرَّ أهل مكة ولم يمنعهم من قصرٍ، ولا من جمعٍ، ويكفينا هذا، والحمد لله.","link":"https://binbaz.org.sa/fatwas/20845/حكم-قصر-الصلاة-في-منى-لاهل-مكة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0641ما هو القول الفصل في مسألة قصر الصلاة في منى لأهل مكة ؟ وما سبب هذا القصر؟ ابن باز.mp3","categories":["أحكام الجمع","المبيت بمنى"]},{"id":830,"question":"شخصٌ يدرس في ألمانيا، ويُواجه مشكلةً وهي: أن أذان المغرب عندهم في الساعة العاشرة، والعشاء الساعة الثانية عشر، والفجر في الساعة الثالثة، ونظرًا لقصر المسافة بين أذان العشاء والفجر وانشغاله بتحصيل العلم في الصباح، فهل يجوز له أن يجمع المغرب مع العشاء جمع تقديمٍ حتى ينام فترةً كافيةً من الليل؟","title":"حكم جمع الصلاة في بلدان ليلها قصير","answer":"الجواب: ليس له أن يجمع بين المغرب والعشاء، بل يُصلي هذه في وقتها، وهذه في وقتها، ويستعين بالله على مُهمات الطلب؛ لأن الجمع إنما يكون لمرضٍ أو سفرٍ أو ما يُلحق بذلك كالمستحاضة، فهذا ليس من هذا القسم.\nوالواجب أن تُكيّف الدروس على الوجه الذي لا يخلّ بالواجب، فإذا كانت الدروس ليست باختياره فإنه يحضر منها ما استطاع، ويُقدم طاعة الله في الجزء الذي تجب فيه الفريضة، ولو فاتته بعضُ الدروس، أما أن يُخضع العبادات لدروسه فلا.","link":"https://binbaz.org.sa/fatwas/20860/حكم-جمع-الصلاة-في-بلدان-ليلها-قصير","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/0655هل يجوز الجمع بين المغرب والعشاء جمع تقديم في البلدان التي يكون الليل فيها قصير؟ ابن باز.mp3","categories":["أحكام الجمع"]},{"id":1758,"question":"اشتهر عن بعض الأئمة الجمع في المطر، مثل: مطر البارحة الخفيف؟","title":"حكم جمع الصلاة في المطر الخفيف","answer":"الجواب:\nعمل الجُهَّال ما هو بحجَّةٍ.\nس: حتى الآن بعض العوام إذا جاء المطر يخرجون من بيوتهم إلى الشوارع والمُنتزهات، يعني: ما يمنعهم المطر الآن؟\nج: المقصود: إذا كان فيه أذًى فذلك عذرٌ لأهل الصَّلاة.","link":"https://binbaz.org.sa/fatwas/21865/حكم-جمع-الصلاة-في-المطر-الخفيف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/حكم الجمع في المطر الخفيف.mp3","categories":["أحكام الجمع"]},{"id":3233,"question":"إذا نزل المطر يجمع الإنسان في بيته؟","title":"هل يجوز جمعُ الصلاة في البيت عند المطر؟","answer":"الجواب: له أن يصلي في بيته.\nس: وله أن يجمع؟\nالشيخ: ترك الجمع أحوط؛ لأن ما عليه مشقة في البيت.","link":"https://binbaz.org.sa/fatwas/23396/هل-يجوز-جمع-الصلاة-في-البيت-عند-المطر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل يجمع الإنسان الصلاة في البيت عند المطر.mp3","categories":["أحكام الجمع"]},{"id":3497,"question":"قول شيخ الإسلام إن الصَّانِع والخَبَّاز يجمع الصلاة إذا خشي على ماله؟","title":"حكم جمع الصَّانِع والخَبَّاز للصلاة","answer":"الجواب: هذا قاله جماعة من أهل العلم، وأن هذا الشغل من الحرج؛ لئلا يُحْْرِج أمته؛ لقول ابن عباس؛ لأنه إذا ترك ذلك قد يشق عليه ويتلف ماله، وقد يكون يضطر إلى هذا، لكن ينبغي للمؤمن أن يحذر الجمع إلا من علة واضحة.\nالواجب أن تُصلى كل صلاة في وقتها؛ لأن الله وقّت المواقيت وألزم بها إلا في السفر، في السفر أو في المطر أو في المرض، أما مع الصحة والإقامة فالواجب الحذر من ذلك إلا من علة شرعية.","link":"https://binbaz.org.sa/fatwas/23675/حكم-جمع-الصانع-والخباز-للصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/مسألة في الجمع الصوري.mp3","categories":["أحكام الجمع"]},{"id":3550,"question":"حديث أن النبي ﷺ جمع في مطر لم يبل أسافل نعالنا، كما يقول الراوي، فهل يدل على جواز الجمع في المطر الخفيف؟","title":"حكم جمع الصلاة في المطر الخفيف","answer":"الجواب: يُنظر في سنده. القاعدة: إنما يُجمع إذا كان مطر يشق على الناس، أو دحض في الطرقات، يكون عذرًا، نعم مثل ما قال ابن عباس: إني كرهت أن أخرجكم في الطين والدحض.","link":"https://binbaz.org.sa/fatwas/23732/حكم-جمع-الصلاة-في-المطر-الخفيف","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/جمع الصلاة في المطر.mp3","categories":["أحكام الجمع"]},{"id":4477,"question":"بعض الفقهاء يشترطون في الجمع أنه ينوي نية الجمع قبل الدخول فيه؟","title":"هل النية شرطٌ للجمع بين الصلاتين؟","answer":"الجواب: هذا المشهور، ولكن الصحيح أنها لا تلزم، الصحيح لا يلزم.... النية، مثلًا: صلَّى المغرب، ثم حدث مطر شديد، جاز له أن يُصلي مع العشاء، كذلك لو بدأ المغرب وكان صحيحًا، ثم أصابه المرضُ، جاز له ..... على الصواب، اختاره شيخُ الإسلام ابن تيمية وجماعة.  ولأن النبي ﷺ ما كان يقول لهم أني أجمع، كان يُصلي المغرب، وما كان يقول لهم أجمع، ولا الظهر، فدلَّ ذلك على أنه لا يشترط، لو أن النية شرط، أخبرهم قال: ترى سنجمع.","link":"https://binbaz.org.sa/fatwas/24756/هل-النية-شرط-للجمع-بين-الصلاتين","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل النية شرطٌ للجمع بين الصلاتين.mp3","categories":["أحكام الجمع"]},{"id":4479,"question":"ما الفرق بين الجمع الصوري والجمع الحقيقي؟","title":"ما معنى الجمع الصوري والحقيقي في الصلاة؟","answer":"الجواب: الحقيقي: كون الصلاة في وقت إحداهما.  والصوري: كون الأولى في آخر وقتها، والثانية في أول وقتها، كلاهما في الوقت، كل واحدةٍ في وقتها، لكن تقاربتا.","link":"https://binbaz.org.sa/fatwas/24758/ما-معنى-الجمع-الصوري-والحقيقي-في-الصلاة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/الجمع الصوري والجمع الحقيقي في الصلاة.mp3","categories":["أحكام الجمع"]},{"id":4763,"question":"أحسن الله عملك لو جمع بين الجمعة والعصر؟","title":"ما حكم جمع العصر مع صلاة الجمعة؟","answer":"لا، الجمعة ما تجمع مع العصر، لا يصلى مع الجمعة تصلى في وقتها، العصر تجمع مع الظهر مع الجمعة لا.\nس: طيب إذا جمعت؟\nالشيخ: يعيدها، إذا جمعوا يعيدون العصر.","link":"https://binbaz.org.sa/fatwas/25122/ما-حكم-جمع-العصر-مع-صلاة-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/fatawa_dross/هل تُصلّى الجمعة مع العصر، وما حكم الجمع.mp3","categories":["أحكام الجمع","صلاة الجمعة"]},{"id":5760,"question":"هل يجوز الجمع بين الظهر والعصر والمغرب والعشاء في المطر؟","title":"جمع الصلاتين في المطر","answer":"الجواب: يجوز إذا وجد السبب، والمطر يشق على الناس؛ جاز الجمع بين الظهر والعصر وبين المغرب والعشاء.  وقال بعض أهل العلم: يجوز المغرب والعشاء فقط؛ لأن الظهر والعصر نهار، ولا فيه مشقة، ولكن ليس هذا بجيد، المشقة حاصلة حتى في النهار إن كان السيل جيدًا، والطرق متعبة من جهة الوحل فإنه يجوز للمسلمين الجمع. النبي ﷺ جمع بين الظهر والعصر وبين المغرب والعشاء في المدينة، قال ابن عباس: لئلا يحرج أمته. وقال بعض أهل العلم: أنه جمع لأجل الدحض في الأسواق، وقيل: لأن هناك مرضًا عامًا شق على الناس فجمع عليه الصلاة والسلام. فالحاصل: إذا كان هناك مرض، أو مطر شديد، فالذي به المرض يجوز له الجمع بين الظهر والعصر وبين المغرب والعشاء، أو في السفر، أو في الأمطار التي تشق على الناس لا بأس، المغرب والعشاء سواء كان في وقت الظهر، أو في وقت العصر، وسواء كان وقت المغرب، أو وقت العشاء جمع تقديم، وجمع تأخير.","link":"https://binbaz.org.sa/fatwas/1080/جمع-الصلاتين-في-المطر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk1_90.mp3","categories":["أحكام الجمع"]},{"id":6256,"question":"ما كلامكم عن الحديث الذي رواه مسلم في صحيحه عن ابن عباس قال: جمع رسول الله ﷺ بين الظهر، والعصر، والمغرب، والعشاء من غير خوف، ولا مطر؟","title":"لما جمع النبي بين الصلاتين من غير خوف ولا مطر؟","answer":"الجواب: هذا حديث مشهور، رواه البخاري ومسلم في الصحيحين: أن النبي -عليه الصلاة والسلام- جمع بين المغرب، والعشاء، صلى ثمان جميعًا، وسبعًا جميعًا، المغرب، والعشاء، والظهر، والعصر، وفي رواية مسلم زيادة: من غير خوف، ولا مطر، وفي رواية أخرى: ولا سفر.  قال العلماء: إنه جمع لعذر غير هذه الثلاث: إما مرض، وإما دحض في الأسواق على آثار المطر، قال ابن عباس: لئلا يحرج أمته، وتحريجها إما بوجود مطر، أو آثاره من وجود الدحض في الأسواق، أو وباء عام، أضعف الناس، وشق عليه، فلهذا جمع -عليه الصلاة والسلام- أو لأنه أراد أن يبين للناس أنه يجوز الجمع، ثم استقرت الشريعة على تحريم الجمع إلا لعذر، كما جاءت الأدلة بعد ذلك، فإنه وقت للناس المواقيت، وبين لهم المواقيت أولها، وآخرها، ثم قال: الصلاة بين هذين الوقتين وقال عمر : الجمع من غير عذر من الكبائر، فالجواب عن هذا من وجوه: أحدها: أنه جمع لعذر شرعي، كالدحض في الأسواق، أو لمرض عام. الوجه الثاني: لئلا يحرج أمته بأسباب وقعت في ذلك الوقت من أجلها جمع؛ لأجل ألا يحرجهم، ولم يبين هذا التحريج ما هو، الذي سبب الجمع.  والوجه الثالث: أنه جمع قبل أن تستقر الشريعة في وجوب كل صلاة في وقتها، وعدم جواز الجمع إلا من علة، ثم استقرت الشريعة على أنه لا يجوز الجمع إلا لعلة واضحة من مرض، أو نحوه، أو سفر. السؤال: ما معنى الدحظ؟ الجواب: الدحظ الزلق، الطين الذي تزل فيه الأقدام.","link":"https://binbaz.org.sa/fatwas/1765/لما-جمع-النبي-بين-الصلاتين-من-غير-خوف-ولا-مطر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_604.mp3","categories":["شروح الحديث","أحكام الجمع"]},{"id":6265,"question":"ما كلامكم عن الحديث الذي رواه مسلم في صحيحه عن ابن عباس قال: جمع رسول الله ﷺ بين الظهر، والعصر، والمغرب، والعشاء من غير خوف، ولا مطر؟","title":"لما جمع النبي بين الصلاتين من غير خوف ولا مطر؟","answer":"الجواب: هذا حديث مشهور، رواه البخاري ومسلم في الصحيحين: أن النبي -عليه الصلاة والسلام- جمع بين المغرب، والعشاء، صلى ثمان جميعًا، وسبعًا جميعًا، المغرب، والعشاء، والظهر، والعصر، وفي رواية مسلم زيادة: من غير خوف، ولا مطر، وفي رواية أخرى: ولا سفر.  قال العلماء: إنه جمع لعذر غير هذه الثلاث: إما مرض، وإما دحض في الأسواق على آثار المطر، قال ابن عباس: لئلا يحرج أمته، وتحريجها إما بوجود مطر، أو آثاره من وجود الدحض في الأسواق، أو وباء عام، أضعف الناس، وشق عليه، فلهذا جمع -عليه الصلاة والسلام- أو لأنه أراد أن يبين للناس أنه يجوز الجمع، ثم استقرت الشريعة على تحريم الجمع إلا لعذر، كما جاءت الأدلة بعد ذلك، فإنه وقت للناس المواقيت، وبين لهم المواقيت أولها، وآخرها، ثم قال: الصلاة بين هذين الوقتين وقال عمر : الجمع من غير عذر من الكبائر، فالجواب عن هذا من وجوه: أحدها: أنه جمع لعذر شرعي، كالدحض في الأسواق، أو لمرض عام. الوجه الثاني: لئلا يحرج أمته بأسباب وقعت في ذلك الوقت من أجلها جمع؛ لأجل ألا يحرجهم، ولم يبين هذا التحريج ما هو، الذي سبب الجمع.  والوجه الثالث: أنه جمع قبل أن تستقر الشريعة في وجوب كل صلاة في وقتها، وعدم جواز الجمع إلا من علة، ثم استقرت الشريعة على أنه لا يجوز الجمع إلا لعلة واضحة من مرض، أو نحوه، أو سفر. السؤال: ما معنى الدحظ؟ الجواب: الدحظ الزلق، الطين الذي تزل فيه الأقدام.","link":"https://binbaz.org.sa/fatwas/1765/لما-جمع-النبي-بين-الصلاتين-من-غير-خوف-ولا-مطر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_604.mp3","categories":["شروح الحديث","أحكام الجمع"]},{"id":6315,"question":"عندنا طائفة في اليمن يقال لهم: المكارمة، يجمعون صلاة الظهر، والعصر باستمرار، ويكون هذا الجمع بين الوقتين، فما رأي الإسلام في ذلك؟ وما هي عقيدة المكارمة؟","title":"حكم الجمع بين الظهر والعصر والمغرب والعشاء من غير عذر","answer":"الجواب: هذا معروف عن الشيعة المكارمة، الشيعة الباطنية، ومعروف عن الشيعة في غالب أنواعهم أنهم يجمعون بين الظهر والعصر، والمغرب والعشاء، وهذا خطأ عند أهل السنة والجماعة، وغلط، النبيﷺ وقت الأوقات، وبينها، فلما بين وقت الظهر، والعصر، وبين المغرب، والعشاء؛ قال: الصلاة بين هذين الوقتين، وعلمه جبرائيل ذلك.. فالوقت محفوظ بينه الله  فهو موضح بالكتاب، والسنة، مبين في القرآن الكريم، وفي السنة المطهرة عن النبي -عليه الصلاة والسلام- فعلى المسلمين أن يعملوا بذلك، وأن يصلوا الصلاة في وقتها، الظهر في وقتها، والعصر في وقتها، والمغرب في وقتها، والعشاء في وقتها، والفجر في وقتها، ولا يجوز لهم التأسي بمن خالف أمر الله، وابتدع في الدين ما لم يأذن به الله من الشيعة، وغير الشيعة، وعلى من يتصل بهم أن ينصحهم، ويقول لهم: إذا كنتم مسلمين؛ فاستقيموا على طريق الإسلام، وصلوا الصلاة لوقتها.  والمكارمة بلغنا عنهم أنهم على دين الباطنية، ولكن يخفون ذلك، وقد سألت بعض رؤسائهم، وقادتهم؛ فأبى أن يخبرني، وقال : نحن على دينكم، وعلى طريقتكم، وليس عندنا ما يخالفكم، فلم يستطع أن يبين لنا شيئًا من عقيدته. ولكن المشهور عن أهل العلم الذين عرفوهم أنهم على دين الباطنية، وعلى دين الرافضة في تعظيم أهل البيت، ودعائهم من دون الله، وعبادتهم من دون الله، كعلي، والحسن، والحسين، وفاطمة، يدعونهم من دون الله، وبهم يستغيثون، ولهم ينذرون، ولهم يذبحون، هكذا بلغنا عن الرافضة، ومن أشباههم من الباطنية.  ولكن بعضهم ينافق؛ إذا كان المسلمون ينافق، ولا يبين ذلك، ويخفيه، ولكنهم قد يتظاهرون بشيء من بدعهم، كهذه البدعة التي هي الجمع بين الصلاتين من دون عذر، أما إن كان لعذر كالمسافر؛ يجمع ما في بأس، المريض يجمع لعذر؛ لا بأس. السؤال: ويقولون في الأذان: حي على خير العمل؟ الجواب:  بدعة أيضًا، قولهم في الأذان: حي على خير العمل، وقولهم في الأذان: أشهد أن عليًّا ولي الله، بدعة، ما هو في الأذان الصحيح، هذه بدعة زادوها، والكلام مثل ما سمعتم، ما في هذه الزيادة، هذه الزيادة باطلة، ولا أساس لها.","link":"https://binbaz.org.sa/fatwas/1896/حكم-الجمع-بين-الظهر-والعصر-والمغرب-والعشاء-من-غير-عذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk3_679.mp3","categories":["أحكام الجمع","شروح الحديث"]},{"id":6441,"question":"صلى رجل بالجماعة المغرب في وقت مطر، وجمع العشاء مع المغرب، ولكن قصر العشاء، وذلك عن عدم معرفته بصفة الجمع، وبعد يوم ذلك علمت بهذا، فقلت لهم أعيدوا صلاتكم، هل أنا مخطئ في هذا؟","title":"حكم قصر العشاء بنية الجمع مع المغرب وقت المطر","answer":"الجواب: أنت مصيب، القصر ليس إلا للمسافر خاصة، فالمريض، والذي يجمع في الحضر ما له قصر، بعض العامة يسمى الجمع قصرًا، القصر كونه يصلي الأربع ثنتين، هذا القصر، أما جمع الظهر إلى العصر، والمغرب إلى العشاء هذا يسمى جمعًا، ما يسمى قصرًا، ضم العصر إلى الظهر في المطر، والمرض، وضم المغرب إلى العشاء في المطر، والسفر، والمرض، هذا يسمى جمعًا، ما يسمى قصرًا، وإذا جمع من أجل المرض، أو من أجل المطر؛ فإنه يصلي الظهر أربعًا، والعصر أربعًا، والعشاء أربعًا، ما يصلي ثنتين، ثنتين، هذه للمسافر خاصة، ما نعلم أنه يصلي ثنتين إلا المسافر في السفر خاصة. أما المريض في البلد، أو في المطر حال المطر، أو الدحض هذا يصلي أربعًا، فإذا جمع بين المغرب، والعشاء؛ صلى المغرب ثلاثًا، والعشاء أربعًا، هذا بإجماع أهل العلم، ليس فيه خلاف بين أهل العلم، أجمع المسلمون على أن صلاة الحضر أربع، ولو في حال المطر، والمرض يصلي أربعًا، الظهر والعصر والعشاء يصليها أربعًا، والفجر على حالها ثنتين، والمغرب على حالها ثلاث، في كل وقت في السفر والحضر.  والذين صلوا العشاء ثنتين بسبب المطر، وهم في الحضر، والبلد فهؤلاء قد غلطوا غلطًا قبيحًا بإجماع المسلمين، وعليهم أن يعيدوا صلاة العشاء، عليهم أن يعيدوها إذا طال الفصل، أما إن نبهوا في الحال كملوها في الحال، وكفى، لكن لو طال الفصل، ما تنبهوا إلا بعد ما طال الفصل؛ يعيدونها، الإمام والمأموم يعيدونها جميعًا. السؤال: يعيدونها جماعة؟ الجواب: إن تيسر جماعة فهو أفضل، وإلا كل يعيدها في بيته.","link":"https://binbaz.org.sa/fatwas/2176/حكم-قصر-العشاء-بنية-الجمع-مع-المغرب-وقت-المطر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_802.mp3","categories":["أحكام الجمع","شروح الحديث"]},{"id":6443,"question":"وآخر يقول: بعد أن كثرت الأمطار في هذه الأيام -والحمد لله رب العالمين-  ما حكم جمع المغرب مع العشاء أثناء نزول المطر وقت المغرب؟ وأيهما أفضل الجمع، أم عدمه؟","title":"حكم جمع الصلاة وقت هطول الأمطار","answer":"الجواب: هذا يختلف، إذا كان المطر جيدًا يؤذي المارة؛ فإن هذا يسيغ الجمع، جمع المغرب والعشاء، وعلى الصحيح من الظهر، والعصر أيضًا؛ إذا دعت الحاجة.  أما إذا كان شيئًا خفيفًا، وليس هناك دحض في الأسواق، مسفلتة، معبدة، والمطر شيء يسير، لا يؤذي؛ فلا جمع، تصلي كل صلاة في وقتها، لكن إذا جاءت المشقة من المطر، أو من الدحض في الأسواق؛ لا بأس بالجمع.","link":"https://binbaz.org.sa/fatwas/2155/حكم-جمع-الصلاة-وقت-هطول-الامطار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_797.mp3","categories":["أحكام الجمع","شروح الحديث"]},{"id":6462,"question":"صلى رجل بالجماعة المغرب في وقت مطر، وجمع العشاء مع المغرب، ولكن قصر العشاء، وذلك عن عدم معرفته بصفة الجمع، وبعد يوم ذلك علمت بهذا، فقلت لهم أعيدوا صلاتكم، هل أنا مخطئ في هذا؟","title":"حكم قصر العشاء بنية الجمع مع المغرب وقت المطر","answer":"الجواب: أنت مصيب، القصر ليس إلا للمسافر خاصة، فالمريض، والذي يجمع في الحضر ما له قصر، بعض العامة يسمى الجمع قصرًا، القصر كونه يصلي الأربع ثنتين، هذا القصر، أما جمع الظهر إلى العصر، والمغرب إلى العشاء هذا يسمى جمعًا، ما يسمى قصرًا، ضم العصر إلى الظهر في المطر، والمرض، وضم المغرب إلى العشاء في المطر، والسفر، والمرض، هذا يسمى جمعًا، ما يسمى قصرًا، وإذا جمع من أجل المرض، أو من أجل المطر؛ فإنه يصلي الظهر أربعًا، والعصر أربعًا، والعشاء أربعًا، ما يصلي ثنتين، ثنتين، هذه للمسافر خاصة، ما نعلم أنه يصلي ثنتين إلا المسافر في السفر خاصة. أما المريض في البلد، أو في المطر حال المطر، أو الدحض هذا يصلي أربعًا، فإذا جمع بين المغرب، والعشاء؛ صلى المغرب ثلاثًا، والعشاء أربعًا، هذا بإجماع أهل العلم، ليس فيه خلاف بين أهل العلم، أجمع المسلمون على أن صلاة الحضر أربع، ولو في حال المطر، والمرض يصلي أربعًا، الظهر والعصر والعشاء يصليها أربعًا، والفجر على حالها ثنتين، والمغرب على حالها ثلاث، في كل وقت في السفر والحضر.  والذين صلوا العشاء ثنتين بسبب المطر، وهم في الحضر، والبلد فهؤلاء قد غلطوا غلطًا قبيحًا بإجماع المسلمين، وعليهم أن يعيدوا صلاة العشاء، عليهم أن يعيدوها إذا طال الفصل، أما إن نبهوا في الحال كملوها في الحال، وكفى، لكن لو طال الفصل، ما تنبهوا إلا بعد ما طال الفصل؛ يعيدونها، الإمام والمأموم يعيدونها جميعًا. السؤال: يعيدونها جماعة؟ الجواب: إن تيسر جماعة فهو أفضل، وإلا كل يعيدها في بيته.","link":"https://binbaz.org.sa/fatwas/2176/حكم-قصر-العشاء-بنية-الجمع-مع-المغرب-وقت-المطر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_802.mp3","categories":["أحكام الجمع","شروح الحديث"]},{"id":6464,"question":"وآخر يقول: بعد أن كثرت الأمطار في هذه الأيام -والحمد لله رب العالمين-  ما حكم جمع المغرب مع العشاء أثناء نزول المطر وقت المغرب؟ وأيهما أفضل الجمع، أم عدمه؟","title":"حكم جمع الصلاة وقت هطول الأمطار","answer":"الجواب: هذا يختلف، إذا كان المطر جيدًا يؤذي المارة؛ فإن هذا يسيغ الجمع، جمع المغرب والعشاء، وعلى الصحيح من الظهر، والعصر أيضًا؛ إذا دعت الحاجة.  أما إذا كان شيئًا خفيفًا، وليس هناك دحض في الأسواق، مسفلتة، معبدة، والمطر شيء يسير، لا يؤذي؛ فلا جمع، تصلي كل صلاة في وقتها، لكن إذا جاءت المشقة من المطر، أو من الدحض في الأسواق؛ لا بأس بالجمع.","link":"https://binbaz.org.sa/fatwas/2155/حكم-جمع-الصلاة-وقت-هطول-الامطار","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk4_797.mp3","categories":["أحكام الجمع","شروح الحديث"]},{"id":7021,"question":"ما ضابط الجمع بين الصلاتين أثناء المطر، أو وقت المطر؟","title":"حكم الجمع بين الصلاتين أثناء المطر","answer":"الجواب:\n\nإذا جاء العذر يجمع بين الصلاتين، الظهر والعصر، والمغرب والعشاء، كالمريض والمسافر، وهكذا المطر الشديد في أصح قولي العلماء، يجمع بين الظهر والعصر، بعض أهل العلم يقولون: الظهر والعصر في النهار ما فيه مشقة، ولكن الصواب أن فيه مشقة إذا كان المطر شديدًا، والأسواق فيها الماء يشق على الناس الخروج إلى العصر، فإذا جمعوا بين الظهر والعصر جمع تقديم؛ فلا بأس كالمغرب، والعشاء، وكالمسافر، وكالمريض، سواء جمع في أول الوقت، أو في وسط الوقت. \n\nالمهم إذا كان هناك ما يشق  عليهم بأن كانوا في المسجد، وحصل المطر الشديد، والأسواق تضرهم فيها الطين، وفيها المياه؛ جمعوا، لا بأس، وإن لم يجمعوا؛ فلهم عذر أن يصلوا في بيوتهم بوجود الأمطار في الأسواق، ووجود الطين، لهم عذر في الصلاة في البيت، إن جمعوا؛ فلا بأس، وإن صلى المسلم في بيته من أجل العذر؛ فلا بأس.\n\nالسؤال: يعني ما يشترط وجود المطر؟\n\nالجواب: المطر، أو الطين، أو الدحض.","link":"https://binbaz.org.sa/fatwas/2957/حكم-الجمع-بين-الصلاتين-اثناء-المطر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk6_1407.mp3","categories":["أحكام الجمع","شروح الحديث"]},{"id":7442,"question":"صليت اليوم مع الجماعة المغرب والعشاء جمعًا في وقت المغرب بسبب المطر، فما حكم ذلك، علمًا أن الطرق ليست بذات مشقة، بل معبدة مع وجود شيء قليل من الماء؟ وآخر مثله : أنا صليت في مسجد العليا، وجمعوا بين المغرب والعشاء وخرجت فهل علينا وزر أفيدونا؟ وآخر يقول: ما حكم جمع الصلاة في حال نزول المطر الشديد في مثل هذا اليوم، نرجو التفضل بذلك جزاكم الله خير الجزاء؟","title":"حكم الجمع بين الصلاتين بسبب المطر","answer":"الجواب: أصل الجمع بين الصلاتين بين المغرب والعشاء لوجود المطر أو الدحض أمر جائز، فعله السلف الصالح، فلا بأس بذلك، جاء في الأحاديث الصحيحة ما يدل عليه، فإذا كانت الجهة التي فيها مسجد فيها مطر يؤذي المصلين في خروجهم وفي دخولهم، أو فيها دحض زلق في طرقها، أو طين يؤذيهم؛ فلا بأس بالجمع، أما إذا كانت محلات المسجد -حي المسجد- ليس فيه أذى، وليس فيه مطر يؤذي المصلين؛ فلا وجه للجمع لمجرد وجود آثار المطر، أما إذا كان هناك مطر يصب عليهم وقت الجمع؛ فلا بأس بذلك، أو هناك دحض يعني زلق في الطرقات وطين في الطرقات فلا بأس. السؤال: والصلاة التي صلوها؟ الجواب: على حسب ما سمعت إن كان لهم عذر؛ فصلاتهم صحيحة، وإن كان ما لهم عذر؛ فعليهم أن يعيدوها.","link":"https://binbaz.org.sa/fatwas/3526/حكم-الجمع-بين-الصلاتين-بسبب-المطر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/jame3_kabeer/fjk8_1830.mp3","categories":["أحكام الجمع","شروح الحديث"]},{"id":8415,"question":"أنا منتسبة إلى إحدى الدوائر، وهذه الدوائر تعمل من الثامنة صباحاً وحتى الثالثة عصراً، وأحياناً أصلي الظهر مع العصر، كيف تنصحونني؟","title":"حكم الجمع بين الصلوات لعلة العمل","answer":"الجواب: الواجب على المؤمن والمؤمنة أداء الصلاة في الوقت، فالعصر تؤدى في وقتها، والظهر تؤدى في وقتها، ولا يجوز الجمع إلا من علة كالمطر على الصحيح، وكالمرض، وكالسفر، فإذا كان هناك علة شرعية فلا بأس بالجمع، وإلا فالواجب أن تصلى كل صلاة في وقتها، الظهر في وقتها، والعصر في وقتها، والدراسة ليست عذراً في الجمع، فالواجب عليك وعلى كل مسلم وعلى كل مسلمة أداء الصلوات في أوقاتها؛ لأن الرسول ﷺ وضحها للأمة وبينها للأمة، وقال بعد ما وقت مواقيت: الصلاة بين هذينن الوقتين في الظهر والعصر والمغرب والعشاء والفجر، فالله بين جل وعلا على لسان نبيه ﷺ الأوقات، فعلى الأمة أن تسمع وتطيع لما بينه عليه الصلاة والسلام، وأن تستقيم على ذلك، وأن لا تترخص في شيء إلا برخصة شرعية ثابتة عن رسول الله عليه الصلاة والسلام. نعم.","link":"https://binbaz.org.sa/fatwas/6299/حكم-الجمع-بين-الصلوات-لعلة-العمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_118/11806.mp3","categories":["أحكام الجمع"]},{"id":9044,"question":"وهذه رسالة وصلت إلى البرنامج من الأخ: حسن الأندنوسي، مقيم بمكة المكرمة يقول فيها: هل يجوز قصر الصلاة لأهل مكة في الحج في يوم عرفة وأيام منى؟ أفيدونا أفادكم الله.","title":"حكم الجمع والقصر لأهل مكة في عرفة ومنى","answer":"الجواب: اختلف العلماء رحمة الله عليهم في هذا، فمنهم من قال: إن أهل مكة يتمون، لأنهم قريبون من عرفات ومنى ومزدلفة، ومنهم من قال: بل يقصرون مع الناس؛ لأن الرسول ﷺ أقرهم في حجة الوداع، ولم يأمرهم بالإتمام، وهذا تشريع منه عليه الصلاة والسلام؛ لأن تقريره حجة، وهكذا أمره ونهيه قوله وفعله عليه الصلاة والسلام، وهذا هو الأظهر والأقرب والله أعلم، أنهم يقصرون مع الناس ويجمعون مع الناس في عرفات ومزدلفة؛ لأن الرسول ﷺ أقرهم على ذلك، ولم يأمرهم بالإتمام ولم ينههم عن الجمع، قال بعض أهل العلم: إن هذا من أجل النسك، وقال بعضهم: إنه من أجل السفر؛ لأن ما بين مكة وعرفات سفر عند بعض أهل العلم.\nوعلى كل تقدير سواء سميناه سفراً أو قلنا من أجل النسك، السنة لهم أن يقصروا مع الناس وأن يجمعوا مع الناس هذا هو الأفضل لهم، أخذاً بظاهر الرخصة؛ لأن هذا لو كان ممنوعاً لبينه النبي ﷺ وقال لهم: أتموا يا أهل مكة لا تجمعوا.\nومعلوم أن تأخير البيان عن وقت الحاجة لا يجوز عند أهل العلم، وهو ﷺ بعثه الله مبيناً ومرشداً وهادياً عليه الصلاة والسلام، فلو كان أهل مكة ممنوعين من القصر، ممنوعين من الجمع؛ لبين لهم ذلك، وأرشدهم إليه في حجة الوداع عليه الصلاة والسلام. نعم.\nالمقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/7213/حكم-الجمع-والقصر-لاهل-مكة-في-عرفة-ومنى","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_224/22410.mp3","categories":["الوقوف بعرفة","أحكام الجمع"]},{"id":9562,"question":"السؤال الثالث في رسالة الأخ صبري الجبوري يقول فيه: إن بعض إخواننا المصلين يجمعون في أوقات الصلاة، مثلًا صلاة الظهر مع العصر، وصلاة المغرب مع العشاء، وصلاة الصبح لوحدها، أي: أن صلاتهم هذا تصبح في ثلاثة أوقات في اليوم الواحد، فهل هذا جائز أم لا أفيدونا أفادكم الله؟","title":"حكم الجمع بين الصلاتين من دون عذر","answer":"الجواب: هذا لا يجوز، الواجب أن تصلوا الصلوات في أوقاتها الخمسة؛ فالظهر في وقتها والعصر في وقتها والمغرب في وقتها والعشاء في وقتها والفجر في وقتها، هكذا وقتها الله  وصلاها جبرائيل بالنبي ﷺ هكذا، والنبي ﷺ لما سئل عن ذلك صلاها بالناس هكذا صلى الظهر حين زالت الشمس وصلى العصر حين صار ظل كل شيء مثله، وصلى المغرب حينما غربت الشمس، وصلى العشاء حين غاب الشفق، وصلى الفجر حين طلوع الفجر هذا في اليوم الأول، وفي اليوم الثاني صلى الظهر حين صار ظل كل شيء مثله، وصلى العصر حين صار ظل كل شيء مثليه، وصلى المغرب بعدما مضى وقته قبل أن يغيب الشفق، وصلى العشاء قبل نصف الليل، وصلى الفجر بعدما أسفر جدًا، وقال الصلاة بين هاذين الوقتين.\nفلا يجوز للمؤمن أن يخالف ما شرعه الله ورسوله وليس له أن يجمع الصلاتين الظهر والعصر والمغرب والعشاء إلا لعذر كالمرض والسفر والمطر، أما من غير عذر فلا. نعم.","link":"https://binbaz.org.sa/fatwas/7727/حكم-الجمع-بين-الصلاتين-من-دون-عذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_193/19303.mp3","categories":["أحكام الجمع"]},{"id":11401,"question":"تقول: أنا عندي عمل مجبرة عليه أذهب في الثانية والنصف بعد الظهر حتى الخامسة والنصف، أو أكثر، والمسافة التي تقطعها السيارة حوالي اثني عشر كيلو ونصف تقريبًا، وفي هذا الوقت تضيع مني صلاة العصر، فأضطر إلى جمعها مع الظهر، وذلك بأن أؤخر صلاة الظهر إلى زوال الشمس، ثم أجمعها جمع تقديم بدون قصر، فهل علي إثم في هذا، أم أن عملي صحيح؟ جزاكم الله خيرًا.","title":"حكم جمع الصلاتين تقديماً أو تأخيراً لأجل الانشغال بعمل","answer":"الجواب:  لا. لا يجوز الجمع، بل صل الصلاة في وقتها، العصر في وقتها، والظهر في وقتها، ليس هذا بسفر، عليك أن تصلي العصر في وقتها، والظهر في وقتها، فإذا تقدمت إلى العمل قبل العصر؛ فصل في الطريق، انزلوا وصلوا في الطريق صلاة العصر، وإلا فتأخر الرحيل إلى أن تصلي صلاة العصر، الفريضة مقدمة على الأعمال، لابد من تحري ما أوجب الله، فإما أن تنزلوا وتصلوا العصر، وإما أن تصلوها قبل السفر ويكون السفر بعد دخول وقت العصر، ليس بسفر الذهاب يعني ....... المقدم: نعم نعم، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/9581/حكم-جمع-الصلاتين-تقديما-او-تاخيرا-لاجل-الانشغال-بعمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_380/38002.mp3","categories":["أحكام الجمع"]},{"id":12173,"question":"يقول: في بعض المساجد يجمعون بين صلاتي الظهر والعصر في وقت صلاة الظهر، ويزعمون أن رسول الله ﷺ جمع بينهما أربعين يومًا في المدينة؛ تخفيفًا على أمته، نرجو التوجيه في ذلك، جزاكم الله خيرًا.","title":"حكم الجمع بين الصلوات","answer":"الجواب:  نعم صح عن النبي ﷺ: أنه صلى الظهر والعصر جميعًا في المدينة، والمغرب والعشاء جميعًا في المدينة، من غير خوف ولا مطر ولا سفر لكن لم يحفظ هذا عنه إلا مرة واحدة -عليه الصلاة والسلام- لا أربعين، فالقول بأنه فعله أربعين هذا باطل لا أساس له من الصحة، وإنما المحفوظ أنه فعل هذا مرة واحدة، قال بعض أهل العلم: لعله كان لوجود دحض في الأسواق من آثار المطر، أو وجود مرض عام، أو وباء عام، أو لأسباب أخرى، قال ابن عباس: \"لئلا يحرج أمته\" يعني: يذهب المشقة عنهم، فإذا حصل ما يشق عليهم من مرض، أو دحض، وآثار المطر في الأسواق، أو ما أشبه ذلك مما فيه مشقة؛ جاز هذا الجمع، أما من غير عذر؛ فالواجب أن لا يفعل؛ لأن الرسول ﷺ وقت المواقيت في المدينة للناس، ووقت، ووقتها له جبرائيل في مكة -عليه الصلاة والسلام- وقال ﷺ: الصلاة بين هذين الوقتين وكان يصلي الظهر في وقتها والعصر في وقتها والمغرب في وقتها والعشاء في وقتها، هذا هو المحفوظ عنه في المدينة، عليه الصلاة والسلام. فالواجب على المسلمين أن يصلوا كل صلاة في وقتها، وأن لا يجمعوا إلا من عذر شرعي، وهذه المرة التي فعلها النبي -صلى الله عليه وسلم- محمولة على أنها كانت لعذر شرعي أراد دفع الحرج عن أمته -عليه الصلاة والسلام- بسبب ذلك العذر الذي لم يذكر في الحديث. والواجب على الأمة أن تأخذ بالأمور المحكمة الواضحة، وأن تدع المشتبهات، يقول الله -جل وعلا- في كتابه العظيم: فَأَمَّا الَّذِينَ فِي قُلُوبِهِمْ زَيْغٌ فَيَتَّبِعُونَ مَا تَشَابَهَ مِنْهُ [آل عمران:7] فلا يجوز للمؤمن أن يأخذ بالمتشابه الذي ليس فيه وضوح، ويدع المحكم الواضح البين، الذي هو صلاته كل صلاة في وقتها في حياته ﷺ في المدينة مدة عشر سنين -عليه الصلاة والسلام- وقد وضح للأمة ذلك وقال: الصلاة بين هذين الوقتين وقال: صلوا كما رأيتموني أصلي. فلا يجوز أن نأخذ بشيء لم يتضح سببه يخالف الأحاديث الصحيحة، والعمل المستمر في حياته ﷺ بل هذا من اتباع المتشابه الذي لا يجوز لأهل الإيمان، فإذا وجدت علة تسوغ الجمع؛ فلا بأس، كالمرض والمطر والسفر ونحو ذلك؛ فلا بأس بذلك، كما فعله النبي -عليه الصلاة والسلام- في أسفاره، ورخص للمستحاضة أن تجمع لعذرها، والمريض كذلك معذور، فلا بأس بذلك للعذر الشرعي، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10359/حكم-الجمع-بين-الصلوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_442/44211.mp3","categories":["أحكام الجمع"]},{"id":12698,"question":"المستمع صبري عبدالله حبيب الحيوري من العراق، بعث برسالة ضمنها جمعًا من الأسئلة، عرضنا بعضًا منها في حلقة مضت، وفي هذه الحلقة يسأل ويقول: إذا كنت في سفر، وحان وقت صلاة الظهر، ولم أصل بسبب السفر، وحين وصولي إلى البيت كان وقت صلاة العصر حاكمًا، فهل يجوز أن أصلي صلاة الظهر قبل صلاة العصر، أو بعد العصر؟ جزاكم الله خيرًا.","title":"وجوب الترتيب في أداء الصلوات","answer":"الجواب: الواجب عليك الترتيب أن تصلي الظهر، ثم العصر، وإذا وصلت البلد، بلدك؛ تصليها تمامًا أربعًا، الظهر أربعًا، والعصر أربعًا، ولو أن الوقت دخل عليك، وأنت في السفر، إذا أخرتها حتى وصلت بلدك؛ فإنك تصليها الظهر أربعًا، ثم تصلي العصر أربعًا، والعكس بالعكس، لو خرجت من البلد بعد الأذان، ولم تصل إلا في السفر، بعدما غادرت البلد؛ تصليها ثنتين، لأن العبرة بوقت الفعل. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/10908/وجوب-الترتيب-في-اداء-الصلوات","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_459/45903.mp3","categories":["أحكام الجمع"]},{"id":12765,"question":"بعد هذا رسالة وصلت إلى البرنامج من الأحساء العيون باعثها المستمع سعد صالح الغريب، أخونا يناقش في قضية، فيقول فيها يا سماحة الشيخ أرجو إجابتي على هذا  هل يجوز الجمع بين الظهر والعصر في أوقات نزول الأمطار، أو اشتداد البرد القارس الذي يؤثر على كبار السن، لاحظنا في الشتاء، وفي بعض المساجد تجمع بين الظهر والعصر، وبعضها لا يجمع إلا بين المغرب والعشاء، وهل هذا ورد عن الرسول ﷺ أما ما بين الظهر والعصر فالبعض يقول: فيه رخصة، والبعض الآخر يقول بعدم الجمع أولى، نريد الإجابة الشافية في هذا الموضوع، جزاكم الله خيرًا، وسدد خطاكم؟","title":"حكم الجمع بين الصلاتين لعذر","answer":"الجواب:  يجوز الجمع في الصحيح من قولي العلماء بين الظهر والعصر وبين المغرب والعشاء في السفر، وفي المرض، وفي المطر كل هذا جائز، وفي الحديث الصحيح أنه ﷺ: جمع بين الظهر والعصر، وبين المغرب والعشاء من غير خوف ولا سفر وفي اللفظ الآخر: من غير خوف ولا مطر. فدل ذلك على أن الجمع للمطر أمر معلوم، ولا حرج فيه، وإن كان ﷺ ترك الجمع لغير عذر، كان يصلي كل صلاة في وقتها، واستقرت الشريعة على أن الصلاة في وقتها، وأنه لا جمع إلا من عذر، ولهذا علمهم ﷺ الأوقات حتى يصلوا الظهر في وقتها، والعصر في وقتها، والمغرب في وقتها، والعشاء في وقتها، والفجر في وقتها، لكن إذا عرض عارض للإنسان من مطر يشق عليه الذهاب إلى المسجد؛ فيجمع الإمام بين الظهر والعصر، والمغرب والعشاء في الأصح. وبعض أهل العلم أجازه في المغرب والعشاء دون الظهر والعصر، والصواب جوازه فيهما جميعًا؛ إذا دعت الحاجة إلى ذلك من المرض، أو من السفر، أو في المطر والزلق، مطر يشق على الناس في طريقهم، يشق عليهم، أو دحض في الأسواق يشق عليهم السير فيها، فالصواب أنه لا حرج في الجمع، نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/10979/حكم-الجمع-بين-الصلاتين-لعذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_419/41914.mp3","categories":["أحكام الجمع"]},{"id":13300,"question":"السائل يقول: ما هو الضابط في جمع الصلوات عند نزول الأمطار، وجهونا بذلك سماحة الشيخ؟","title":"ضابط جمع الصلوات في المطر","answer":"الجواب: الجمع رخصة عند نزول المطر، أو عند المرض، وفي السفر كذلك، الله -جل وعلا- يحب أن تؤتى رخصه، فإذا نزل بالمسلمين مطر يشق عليهم معه أداء الصلاة في وقتها، العشاء أو العصر مع الظهر؛ فلا بأس أن يجمعوا كما يجمع في السفر، المسافر يجمع بين الظهر والعصر والمغرب والعشاء، فهكذا المسلمون في القرى والأمصار إذا نزلت بهم الأمطار، وصارت الأسواق فيها الدحض والزلق والسيول، فإنهم يجمعون بين المغرب والعشاء جمع تقديم؛ لئلا يشق عليهم الخروج للعشاء مع وجود المطر المتتابع، أو الزلق في الأسواق، والدحض، والطين في الأسواق، والظهر والعصر في الجمع بينهما خلاف بين أهل العلم. والصواب: أنه لا حرج في الجمع بينهما عند وجود العذر الشرعي، إذا وجد العذر الشرعي؛ جاز الجمع كما جمع النبي ﷺ في السفر، وفي الخوف، والمرض، كله جائز، لا بأس، النبي ﷺ حث الأمة على ما فيه الرفق، وما فيه الخير لها، وأحب، قال: إن الله يحب أن تؤتى رخصه كما يكره أن تؤتى معصيته وقال ابن عباس -رضي الله عنهما-: \"إن النبي ﷺ جمع بين الظهر والعصر، وبين المغرب والعشاء من غير خوف ولا مطر\" وفي رواية: \"من غير خوف ولا سفر\" قيل لابن عباس؟ قال: \"لئلا يحرج أمتة\" يعني: لئلا تقع أمته في الحرج، فإذا كان هناك مطر، أو خوف، أو مرض؛ جاء الحرج؛ فلا بأس أن يجمعوا.  والحديث هذا قال جماعة من أهل العلم: إنه منسوخ، ولكن الصواب أنه غير منسوخ، لكن المحمول على أنه جمع لعذر شرعي، غير الخوف، وغير المطر، وغير السفر كالدحض، فإن الدحض عذر شرعي أيضًا، فإذا كانت الأسواق فيها زلق، وطين حول المسجد، ولو لبعض الجماعة؛ فإن هذا عذر، إذا كان بعض الجماعة قرب المسجد، ما عليهم مشقة، لكن بقية الجماعة عليهم مشقة من الطين، والمنازع، أي: منازع السيل هذا عذر شرعي. وإذا تركوا الجمع بين الظهر والعصر خروجًا من الخلاف، وصبروا على بعض المشقة؛ فهذا حسن -إن شاء الله- لكن مع وجود المشقة، الدليل يقتضي الجمع بين الظهر والعصر، وبين المغرب والعشاء عند الحاجة، والمشقة، نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11585/ضابط-جمع-الصلوات-في-المطر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_522/52206.mp3","categories":["أحكام الجمع"]},{"id":13428,"question":"هذا سائل يقول: إذا كان فيه مطر كثير، وصليت في مسجد لم يجمع، ولما خرجت سمعت الإقامة لصلاة العشاء؟ هل يجوز أن أجمع معهم؟","title":"لم يجمع إمامهم للمطر هل له أن يذهب لمسجد آخر؟","answer":"الجواب: ينبغي ألا تجمع؛ لأنك فرقت بينهما تفريقًا كثيرًا بين المغرب والعشاء، صار الفصل طويلًا، فينبغي أن تدع ذلك خروجًا من خلاف العلماء، تصلي مع أصحابك العشاء -إن شاء الله- ولا تصل مع هؤلاء؛ لأنك فرقت بينهما فرقًا طويلًا. نعم. المقدم: جزاكم الله خيرًا سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/11722/لم-يجمع-امامهم-للمطر-هل-له-ان-يذهب-لمسجد-اخر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_527/52705.mp3","categories":["أحكام الجمع"]},{"id":13527,"question":"حكم من يجمع بين الصلاتين من أجل العمل؟ وهل صحيح أن الرسول ﷺ جمع بين الصلاتين؟","title":"حكم الجمع بين الصلاتين من أجل العمل","answer":"الجواب: ليس له الجمع من أجل العمل، بل كل صلاة في وقتها، وإنما جمع النبي ﷺ لأسباب إما لسفر وإلا لمرض، أو الدحض، والزلق والمطر، أما الجمع بدون سبب ما كان يجمع -عليه الصلاة والسلام- وما ورد من حديث ابن عباس: \"أنه ﷺ جمع بين الظهر والعصر، وبين المغرب والعشاء من غير خوف، ولا مطر\" وفي بعض الروايات: \"من غير خوف ولا سفر\" فهذا محمول على عذر آخر، كالدحض والزلق، أو المرض، قد استقرت الشريعة على أنه لا يجوز الجمع إلا لعذر شرعي، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/11875/حكم-الجمع-بين-الصلاتين-من-اجل-العمل","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_532/53210.mp3","categories":["أحكام الجمع"]},{"id":13691,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من المستمع محمد العمري من الرياض، الأخ محمد له جمع من الأسئلة من بينها سؤال يقول: ما حكم جمع صلاة الظهر والعصر في حال المطر؟","title":"حكم الجمع بين الظهر والعصر لعذر المطر","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه. أما بعد.  فهذه المسألة فيها خلاف بين أهل العلم، هل يجمع بين الظهر والعصر في المطر والدحض، أم لا؟ على قولين، والصواب: أنه لا بأس، كالمغرب والعشاء؛ فلا بأس أن يجمع الإمام بالناس في الظهر والعصر من أجل المطر الذي يؤذيهم، أو الدحض في الأسواق، والزلق في الأسواق؛ لأن الله -جل وعلا- يقول: يُرِيدُ اللَّهُ بِكُمُ الْيُسْرَ [البقرة:185] ويقول سبحانه: وَمَا جَعَلَ عَلَيْكُمْ فِي الدِّينِ مِنْ حَرَجٍ [الحج:78] والنبي ﷺ: \"جمع في المدينة من غير خوف ولا مطر\" وفي رواية: \"من غير خوف ولا سفر\". فدل ذلك على أن المطر مما يسوغ الجمع، وهكذا آثاره من الدحض في الأسواق، والطين في الأسواق الذي يتأذى به المصلون، هو عذر شرعي أيضًا. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12060/حكم-الجمع-بين-الظهر-والعصر-لعذر-المطر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_481/48101.mp3","categories":["أحكام الجمع"]},{"id":14307,"question":"أولى رسائل هذه الحلقة رسالة وصلت إلى البرنامج من الجمهورية العربية اليمنية محافظة إب صاحب الرسالة هو المستمع عبد الكريم أحمد صالح، الأخ عبد الكريم يسأل ويقول: هل يجوز للمرأة أن تجمع بين صلاة العصر والظهر؟ أو أنه لا يجوز؟ وهل يجب عليها أن تؤدي السنة قبل الصلاة؟ أجيبونا جزاكم الله خيرًا.","title":"حكم الجمع بين الصلاتين للمرأة بغير عذر","answer":"الجواب: بسم الله الرحمن الرحيم، الحمد لله، وصلى الله وسلم على رسول الله، وعلى آله وأصحابه ومن اهتدى بهداه.\nأما بعد: فالرجل والمرأة في هذا الباب سواء، على كل منهما أن يصلي الصلاة لوقتها، فالظهر في وقتها، والعصر في وقتها، والمغرب في وقتها، والعشاء في وقتها، والفجر في وقتها، على الرجل والمرأة جميعًا؛ لأن النبي ﷺ وقت مواقيت وقال عليه الصلاة والسلام: الصلاة بين هذين الوقتين. فعلى المرأة أن تصلي الظهر في وقتها، والعصر في وقتها، ولا تجمع بينهما، وهكذا المغرب في وقتها، والعشاء في وقتها، ولا تجمع بينهما كالرجل، وهكذا الفجر في وقتها، إلا لعذر شرعي، كالمسافر لا بأس أن يجمع بين الصلاتين، والمريض من الرجال والنساء لا بأس أن يجمع بين الصلاتين، وهكذا في المطر الذي يتأذى به المسلم لا بأس أن يجمع المصلون في المساجد عند وجود الأمطار والدحض في الطرق ما يحصل به الأذى يشرع لهم الجمع بين المغرب والعشاء، وهكذا بين الظهر والعصر في أصح قولي العلماء تسهيلًا من الله  لعباده ورحمة لعباده، وهو سبحانه يحب أن تؤتى رخصه كما يكره أن تؤتى معصيته.  وهكذا المرأة إذا كانت مستحاضة كما في حديث حمنة بنت جحش أن النبي ﷺ رخص لها في تأخير الظهر وتعجيل العصر والجمع بينهما، وتأخير المغرب وتعجيل العشاء والجمع بينهما من أجل استحاضتها، من أجل استمرار الدم معها، فهذا عذر أيضًا. أما امرأة سليمة معافاة ليست مسافرة فليس لها أن تجمع، وهكذا الرجل ليس له أن يجمع إلا بالعذر الشرعي. وفق الله الجميع. نعم.\nالمقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/12780/حكم-الجمع-بين-الصلاتين-للمراة-بغير-عذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_622/62201.mp3","categories":["أحكام الجمع","قضايا المرأة"]},{"id":14636,"question":"في إحدى المرات كنا عند بعض الجماعة، فنزل المطر، وكان ذلك وقت صلاة المغرب، وبعد أن صلينا المغرب قال أحدهم: أقيموا صلاة العشاء، فجمعنا العشاء مع المغرب، ولم أكن أعرف شيئًا عن ذلك؛ ولما سألته قال: قال رسول الله ﷺ: إذا نزل خير فاجمعوا ولم أذكر بالضبط نص الحديث، فهل صلاتنا صحيحة؟ وهل ورد ذلك عن الرسول ﷺ؟أفيدونا، جزاكم الله خيرًا.","title":"حكم الجمع بين الصلاتين في المطر","answer":"الجواب: الجمع في المطر وفي المرض مشروع، وهو من الرخص التي جاء بها الإسلام.  وأما الحديث الذي ذكره لك الشخص إذا نزل خير فاجمعوا هذا لا نعلم له أصلًا، ولا يعرف في السنة عن النبي -عليه الصلاة والسلام-، ولكنه من عمل السلف، من عمل السلف الصالح الجمع في المطر، وهكذا دل الحديث على ذلك حيث قال ابن عباس -رضي الله عنهما-: \"إن النبي جمع ﷺ بين المغرب والعشاء والظهر والعصر في غير خوف ولا مطر ولا سفر\" فدل ذلك على أن الجمع للمطر أمر معلوم، كما أن الجمع للسفر أمر معلوم. فإذا كان هناك مطر يشق على الناس، أو دحض في الأسواق وزلق في الأسواق يشق على الناس شرع الجمع من باب التيسير على المسلمين والتسهيل عليهم، وقبول رخص الله ، فقد قال -عليه الصلاة والسلام-: إن الله يحب أن تؤتى رخصه كما يكره أن تؤتى معصيته. وهكذا المريض يجمع لدفع المشقة، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13134/حكم-الجمع-بين-الصلاتين-في-المطر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_627/nour_62705.mp3","categories":["أحكام الجمع"]},{"id":14835,"question":"من إيرلندا هذه الرسالة وصلت إلى البرنامج من أحد الإخوة المستمعين من هناك، يقول: أنا طالب أحضر الدراسات العليا في الهندسة هنا في مجتمع غير مسلم إيرلندا، هل يجوز لي الجمع والقصر في الصلاة؟","title":"حكم الجمع والقصر للمقيم في مجتمع غير مسلم","answer":"الجواب: إذا كنت مقيمًا في الدولة هذه إقامة معينة، فليس لك القصر، وليس لك الجمع، بل تصلي أربعًا، وتصلي كل صلاة في وقتها، ما دمت قد نويت الإقامة أكثر من أربعة أيام تصلي الظهر أربعًا، والعصر أربعًا، والعشاء أربعًا، كل واحدة في وقتها، المغرب في وقتها، والفجر في وقتها، هذا هو الواجب عليك. أما لو كنت مقيمًا إقامة لا تدري متى تنتهي، هل هي يومان، أو ثلاثة، أو أربعة أو أكثر؟ يعني: إقامة ما تعلم مداها، فهذه لا تمنع من القصر، ولا تمنع من الجمع، لك أن تقصر، ولك أن تجمع، وهكذا لو كانت إقامة محدودة بأربعة أيام، أو أقل، فإنك تقصر فيها إذا شئت وتجمع، ولا حرج في ذلك.  أما إذا عزم الإنسان على الإقامة أكثر من أربعة أيام للدراسة، أو غير الدراسة، أو لحاجة من الحاجات، فإنه يكمل أربعًا، ولا يجمع، نعم.\nالمقدم: جزاكم الله خيرًا. إذا كانت مدة الدراسة سبع سنوات مثلًا سماحة الشيخ؟ الشيخ: لا، لا يجمع. المقدم: لا يجمع ولا يقصر؟ الشيخ: ولا يقصر، نعم. المقدم: ولا يفطر أيضًا؟\nالشيخ: ولا يفطر أيضًا، بل يصوم مع الناس، نعم.\nالمقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/13333/حكم-الجمع-والقصر-للمقيم-في-مجتمع-غير-مسلم","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_638/nour_63818.mp3","categories":["أحكام الجمع"]},{"id":15023,"question":"هذه الرسالة وردتنا من علي سالم يقول: من طرف علي سالم من جدة تصلكم هذه الرسالة، مهنئًا لكم فيها بسلامة حج هذا العام، ومباركًا لكم بالعام الجديد، وراجيًا أن تجيبونا على بعض هذه الأسئلة، حيث وقع لنا شك فيها، يقول: ما هو الراجح لأهل مكة بالنسبة للصلاة في عرفة ومزدلفة ومنى؟","title":"حكم الجمع والقصر لأهل مكة في عرفة ومنى والمزدلفة","answer":"الجواب: النبي ﷺ صلى بالناس في عرفات وفي مزدلفة وفي منى قصرًا، ركعتين ركعتين، الظهر والعصر والعشاء، ومعه أهل مكة وغيرهم، ولم يأمرهم بالإتمام، فدل ذلك على أن أهل مكة مع الناس، سواء سمينا الخروج إلى منى وعرفات سفرًا، أو لم نسمه سفرًا، سواء سميناه سفرًا، أم لم نسمه سفرًا، فإنهم يقصرون مع الحجيج، وهكذا جمع النبي ﷺ في عرفات وفي مزدلفة، بين الظهر والعصر في عرفة، والمغرب والعشاء في مزدلفة، والناس معه، ولم يقل: يا أهل مكة أتموا، ولم يقل لهم: لا تجمعوا، فدل ذلك على أنه لا حرج عليهم في الجمع والقصر. وهذا هو المختار، وهو الأرجح من أقوال أهل العلم في هذه المسألة، نعم.","link":"https://binbaz.org.sa/fatwas/13528/حكم-الجمع-والقصر-لاهل-مكة-في-عرفة-ومنى-والمزدلفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_653/nour_65304.mp3","categories":["أحكام الجمع","مسائل متفرقة في الحج والعمرة"]},{"id":15137,"question":"من المدرس محمد يحيى المصطفى من رفحا العجرمية، وردتنا هذه الرسالة، يقول فيها: في مساء أحد الأيام كنت في مجلس عند رجل، وقد اجتمع ما يزيد على خمسة عشر رجلًا لوجود عرس عنده، وكل واحد منا ينوي أن يسهر، يتعلل في هذا المكان، كانت السماء تمطر مطرًا متقطعًا، وليس مستمرًا أو وسطًا لا هو بالشديد الغزير، ولا هو بالخفيف، وحالة الطقس متوسطة البرودة، وعندما جاء وقت صلاة المغرب صليناها جماعة في نفس المكان، فقال بعضهم: يجب أن نجمع صلاة العشاء مع المغرب؛ لأن السماء تمطر والطقس باردة. علمًا أننا سنمكث إلى بعد صلاة العشاء، فهل يجوز الجمع والناس في أماكنهم أم لا؟وفقكم الله.","title":"حكم الجمع لعذر المطر والبرد في غير المسجد","answer":"الجواب: إذا كان الواقع مثلما ذكر فلا حرج في الجمع؛ لأنه عذر، وإن صلوا المغرب وحدها، وتركوا العشاء في وقتها، فلا بأس. المقصود: أنه ما دامت السماء تمطر، والطقس كما قال فيه البرودة، وبكل حال فالمطر عذر، المطر عذر مطلقًا ما دام متصلًا، وليس بالخفيف، بل يبل الثياب، ويؤذي من يخرج إلى بيته، أو إلى الطرقات، فهذا عذر شرعي في الجمع بين الصلاتين، نعم.\nالمقدم: لكنهم لن يخرجوا من المكان الذي هم فيه؟ الشيخ: تعمهم الرخصة، وإن أجلوا العشاء في وقتها فحسن، ولكن تعمهم الرخصة، نعم.","link":"https://binbaz.org.sa/fatwas/13636/حكم-الجمع-لعذر-المطر-والبرد-في-غير-المسجد","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_665/nour_66501.mp3","categories":["أحكام الجمع"]},{"id":15206,"question":"يقول هذا السائل الذي رمز لاسمه بـ(م. ح): سماحة الشيخ، بعض الناس يقولون بأنه لا يجوز أن نجمع صلاة العصر مع أي صلاة، وبعضهم يقول: الأفضل أن لا نجمعها مع الصلوات الأخرى، فما رأي سماحتكم في ذلك؟","title":"حكم جمع صلاة العصر مع الظهر أو الجمعة","answer":"الجواب: العصر تجمع مع الظهر في حق المريض والمسافر، العصر تجمع مع الظهر جمع تقديم وجمع تأخير في حق المريض وحق المسافر، لكن لا تجمع العصر مع الجمعة، يوم الجمعة إذا صلى مع الناس الجمعة لا يصلي معها العصر، يصلي العصر في وقتها، إذا صلى الجمعة مع الناس مر البلد وصلى معهم الجمعة وهو مسافر يصلي العصر في وقتها.  وأما في غير الجمعة يجمع العصر مع الظهر، لا بأس إذا كان مريضًا يشق عليه عدم الجمع أو مسافرًا لا بأس، نعم. المقدم: أحسن الله إليكم، وبارك فيكم.","link":"https://binbaz.org.sa/fatwas/13697/حكم-جمع-صلاة-العصر-مع-الظهر-او-الجمعة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_564/56424.mp3","categories":["أحكام الجمع"]},{"id":15469,"question":"هذا السائل يقول: سؤالي عن حكم جمع الصلوات جمع تقديم في المطر، وما الضابط في ذلك؟مأجورين.","title":"ضابط جمع التقديم في المطر","answer":"الجواب: إذا كان المطر يشق على الناس، أو الطرق فيها زلق وطين دحض، فإنه يجمع جمع تقديم في المغرب والعشاء، وهكذا الظهر والعصر على الصحيح، لو كانت الطرقات فيها مضرة على المصلين من شدة المطر، فإنه يجمع أيضًا على الصحيح جمع تقديم؛ لأن الله -جل وعلا- قال: وَمَا جَعَلَ عَلَيْكُمْ فِي الدِّينِ مِنْ حَرَجٍ [الحج:78] وقد ثبت عنه ﷺ «أنه كان يجمع في الحضر من غير خوف ولا مطر ولا سفر» ثم ترك ذلك -عليه الصلاة والسلام-؛ فصار الجمع إنما هو للعذر، وجمع الصحابة للعذر -رضي الله عنهم وأرضاهم-، الذي هو المطر والدحض، يعني: الزلق، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/13994/ضابط-جمع-التقديم-في-المطر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_568/56817.mp3","categories":["أحكام الجمع"]},{"id":15864,"question":"هذا سائل يقول: سؤالي عن حكم جمع الصلوات جمع تقديم في المطر، وما الضابط في ذلك؟ مأجورين.","title":"الضابط في جمع الصلوات حال المطر","answer":"الجواب: إذا كان المطر يشق على الناس، أو الطرق فيها زلق وطين -دحض-، فإنه يجمع جمع تقديم للمغرب والعشاء، وهكذا الظهر والعصر على الصحيح، لو كانت الطرقات فيها مضرة على المصلين لشدة المطر؛ فإنه يجمع أيضًا على الصحيح جمع تقديم؛ لأن الله -جل وعلا- قال: وَمَا جَعَلَ عَلَيْكُمْ فِي الدِّينِ مِنْ حَرَجٍ [الحج:78] وقد ثبت عنه ﷺ أنه كان يجمع في الحضر من غير خوف ولا مطر ولا سفر، ثم ترك ذلك -عليه الصلاة والسلام-، فصار الجمع إنما هو للعذر، وجمع الصحابة للعذر -رضي الله عنهم وأرضاهم-، سواء المطر والدحض، نعم، يعني: الزلق، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/14455/الضابط-في-جمع-الصلوات-حال-المطر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_576/57626.mp3","categories":["أحكام الجمع"]},{"id":16266,"question":"هل صحيح أن الرسول ﷺ جمع من غير مرض، أو مطر؟","title":"توجيه لجمع النبي ﷺ الصلاة من غير مرض أو مطر","answer":"الجواب: نعم، ثبت عن النبي ﷺ من حديث ابن عباس: «أنه جمع من غير خوف، ولا سفر، ومن غير خوف، ولا مطر» قال بعض أهل العلم: جمع لعلة أوجبت ذلك، إما مرض، أو غيره من العلل التي توجب الجمع، وقال بعضهم: إن هذا منسوخ، كان في أول الإسلام ثم نسخ. والمقصود: أنه لا يجوز الجمع إلا لعلة، أما الحديث المذكور صحيح، لكنه محمول على أنه جمع لعذر، أو كان جائزًا في الأصل، ثم نسخ، قال ابن تيمية -رحمه الله-: إن العلماء أجمعوا على عدم العمل بهذا الحديث، يعني: مع عدم العذر، لا يجوز الجمع إلا لعذر، كالمرض، كالمطر، كالدحض الذي في الأسواق، الزلق في الأسواق بسبب المطر، يجمع بينهما، الظهر والعصر، والمغرب والعشاء، أو كان مسافرًا لا بأس إذا كان في السفر، نعم. المقدم: أحسن الله إليكم سماحة الشيخ.","link":"https://binbaz.org.sa/fatwas/14948/توجيه-لجمع-النبي-ﷺ-الصلاة-من-غير-مرض-او-مطر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_581/58104.mp3","categories":["أحكام الجمع"]},{"id":16471,"question":"المستمع: أمجد أحمد مجدي من جمهورية مصر العربية يقول: عملي سائق، وفي بعض الأوقات أجمع الصلاتين الظهر والعصر، وهذا لكوني مجبر بذلك، لأني أعمل ثمان ساعات، أو عشر يوميًّا، فهل يجوز ذلك؟","title":"حكم الجمع بين الصلاتين بغير عذر","answer":"الجواب: ليس لك الجمع وأنت مقيم، بل عليك أن تصلي مع الناس كل صلاة في وقتها. أما إذا كنت مسافرًا في طريق إلى بلد من البلدان، مسافرًا، فلك الجمع مثل غيرك من المسافرين، أما ما دمت في البلد بين بيتك وبين محل العمل؛ فليس لك أن تجمع، بل عليك أن تصلي مع الناس، وليس لك أن تطيع غيرك في معصية الله، بل صل مع الناس الظهر في الجماعة، والعصر في الجماعة، ولا تجمع، وهكذا المغرب والعشاء إذا كان العمل في الليل، صل مع الناس نعم، وهكذا أصحابك -معازيبك- عليهم أن يصلوا في الجماعة، ولا يجوز لهم أن يصلوا جمعًا، نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/15210/حكم-الجمع-بين-الصلاتين-بغير-عذر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_813/nour_81310.mp3","categories":["أحكام الجمع"]},{"id":16679,"question":"هذا سؤال من السائل حازم حسين من الأردن يقول: هل صلاة الظهر، والعصر جمعًا، وقصرًا في نمرة أمر واجب؟ أم يجوز أن أصليهما في وقت كل منها كاملتين؟","title":"حكم جمع وقصر الظهر والعصر بعرفة","answer":"الجواب: صلاتهما جمعًا وقصرًا في عرفات، في عرنة ما هو في نمرة، في عرنة، صلاها النبي ﷺ في عرنة.. في غرب عرفات، هذا مستحب، وسنة مؤكدة، ولا ينبغي للمؤمن أن يخالف السنة، لكن ليس بواجب عند أهل العلم، بل هو سنة، فإن المسافر لو أتم صحت صلاته، لكن هنا متأكد؛ لأن الرسول فعله ﷺ وقال خذوا عني مناسككم فلا ينبغي له أن يخالف السنة، بل يصلي مع الناس قصرًا وجمعًا جمع تقديم، ثم يتوجه إلى محل الوقوف في نفس عرفة. ولو صلاهما في عرفة، ولم يصل في عرنة، ولا في نمرة؛ فلا بأس، فإن الناس في هذه العصور يحتاجون إلى التخلص من الزحام، فبقاؤه في نمرة، أو في عرنة قد يشق عليه في آخر النهار عند دخوله في عرفة، فإذا دخل عرفة؛ ضحى، ونزل بها ضحى، وبقي بها حتى يصلي الظهر، والعصر فيها -في عرفات- جمع تقديم، فلا بأس. وإن نزل في نمرة، وصلى في عرنة كما فعل النبي ﷺ ثم دخل عرفات، فهذا أفضل إذا تيسر، ولكنه في الوقت الحاضر قد يصعب على غالب الناس بسبب كثرة الناس، وزحام السيارات، والله المستعان، نعم.  المقدم: جزاكم الله خير الجزاء.","link":"https://binbaz.org.sa/fatwas/15408/حكم-جمع-وقصر-الظهر-والعصر-بعرفة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_818/nour_81805.mp3","categories":["أحكام الجمع","الوقوف بعرفة"]},{"id":17334,"question":"هل صحيح أن الحاج يقصر من صلاته الرباعية، أيام حجه بما فيها أيام التشريق الثلاث؟","title":"حكم قصر الصلاة للحجاج من أهل مكة","answer":"الجواب: الحاج نعم يقصر في عرفة، وفي مزدلفة، وفي منى مثل ما فعل النبي ﷺ ولم يقل: يا أهل مكة أتموا، فقصر معه الناس في عرفة، صلوا الظهر ثنتين، والعصر ثنتين، وفي مزدلفة صلوا معه المغرب ثلاثًا، والعشاء ثنتين، ولم يقل: يا أهل مكة أتموا، فدل على أن الحجاج يفعلون مثلما يفعل غيرهم، يقصرون في منى، وفي عرفة، وفي مزدلفة، نعم. المقدم: أحسن الله إليكم.","link":"https://binbaz.org.sa/fatwas/16186/حكم-قصر-الصلاة-للحجاج-من-اهل-مكة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_769/nour_76908.mp3","categories":["أحكام الجمع","مسائل متفرقة في الحج والعمرة"]},{"id":18728,"question":"يقول السائل: سماحة الشيخ، هل يجوز الجمع بين صلاة الظهر والعصر بدون سفر لأي سبب آخر؟","title":"حكم الجمع بين الظهر والعصر بدون سبب","answer":"الجواب: الصواب لا يجوز، كان يجوز في الأول، ثم شرع الله الأوقات، كان في أول الإسلام يجوز، ثم شرع الله الأوقات، فوجب أن تفعل الصلوات في وقتها، الظهر في وقتها، والعصر في وقتها، والمغرب في وقتها، والعشاء في وقتها، إلا لعلة كالسفر يجوز الجمع، أو مرض، أو مطر، إن كان مطر أو دحض يجوز الجمع، كما بيَّنه النبي -عليه الصلاة والسلام-، نعم.","link":"https://binbaz.org.sa/fatwas/17854/حكم-الجمع-بين-الظهر-والعصر-بدون-سبب","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_789/nour_78909.mp3","categories":["أحكام الجمع"]},{"id":19059,"question":"في سؤال لها تقول: في سفري أخرج في الصباح وأصل المنزل بعد العشاء بفترة، فأصلي قبل الخروج الظهر والعصر، والمغرب والعشاء قصر مع بعضها، هل هذا صحيح أم لا؟وكذلك إذا خرجت للسوق قبل العصر وأصل المنزل بعد العشاء هل أصلي العصر والمغرب قبل الخروج من المنزل؛ لأن وقت السوق محدود؟","title":"لا يجوز الجمع بين الصلاتين للذهاب إلى السوق","answer":"الجواب: ليس لك قصر ولا جمع، هذا غلط عظيم، الواجب عليك أن تصلي الصلاة في وقتها؛ الظهر أربع، والعصر أربع، والمغرب ثلاث، والعشاء أربع، ولو كنت في السوق صلي في السوق في الوقت، والحمد لله. أما الجمع بين الصلاتين هذا منكر ليس لك الجمع من أجل السوق، والبيع والشراء، ولكن تصلين في البيت إذا خرجت بعد زوال الشمس بعد أذان الظهر، صلي في البيت الظهر فقط بس، وإن كان بعد العصر إذا أذن صلي العصر فقط ثم اذهبي للسوق. فإذا جاء المغرب وأنت في السوق اذهبي إلى البيت، وصلي في البيت، أو صلي في السوق إن كان البقاء لا بد منه، صلي في السوق، ثم ابقي في السوق حتى يأتي وقت العشاء، ثم صلي العشاء في السوق. أما الجمع بينهما هذا منكر عظيم لا يجوز، وإذا كنت فعلت شيئًا من هذا فعليك الإعادة، إذا كنت صليت العصر قبل وقتها أو الظهر قبل وقتها، أو المغرب قبل وقتها، أو العشاء قبل وقتها؛ فعليك الإعادة مع التوبة إلى الله؛ هذا منكر عظيم، نسأل الله السلامة والعافية. المقدم: اللهم آمين، جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18240/لا-يجوز-الجمع-بين-الصلاتين-للذهاب-الى-السوق","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_796/nour_79613.mp3","categories":["أحكام الجمع","قضايا المرأة"]},{"id":19169,"question":"أخونا محمد صالح ناجي من مكتبة المجتمع بالخبر عرضنا جزءًا من أسئلته في حلقة مضت، وفي هذه الحلقة يسأل ويقول: ما رأيكم في النساء اللائي يجمعن بين الصلوات؛ نظرًا لانشغالهن بأمور البيت؟","title":"حكم جمع النساء بين الصلوات لانشغالهن بأمور البيت","answer":"الجواب: لا يجوز هذا، لا، ليس لهن الجمع، الواجب عليهن أن يصلين كل صلاة في وقتها مثل الناس، الظهر في وقتها، والعصر في وقتها، والعشاء في وقتها، والمغرب في وقتها، هكذا شرع الله سبحانه لعباده. نعم. المقدم: جزاكم الله خيرًا.","link":"https://binbaz.org.sa/fatwas/18378/حكم-جمع-النساء-بين-الصلوات-لانشغالهن-بامور-البيت","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_887/nour_88706.mp3","categories":["أحكام الجمع"]},{"id":19253,"question":"أحد الإخوة المستمعين بعث برسالة يسأل فيها سماحتكم عن أمرين:الأمر الأول هو: يقول فيه: عند هطول المطر وخاصة في المساء يؤذن لصلاة المغرب، وبعد تأدية الصلاة تقام صلاة العشاء جمعًا، وذلك رأفة بالمصلين من أجل المطر، هل يجوز ذلك مع أن الوقت تغير عن الماضي، وأصبح كل شيء مجهز لدى البعض مثل المواصلات وما أشبه ذلك؟","title":"حكم الجمع بين الصلاتين في المطر","answer":"الجواب: نعم، رخصة من الله، فإذا جاء وقت المطر لا بأس بالجمع رخصة، يستحب الجمع من أجل رحمة الناس، والتيسير عليهم وعدم إلجائهم إلى التأذي بالخروج، ولو لم يجمعوا جاز للإنسان أن يصلي في بيته، وقد ثبت عنه ﷺ أنه أمر بالصلاة في البيوت عند وجود المطر قال: صلوا في رحالكم. فالحاصل أنه إذا صار في وقت مطر أو دحض في الأسواق، وزلق وطين، فإن السنة الجمع بين الظهر والعصر والمغرب والعشاء، ومن لم يجمع أو شق عليه الخروج، فله الصلاة في بيته عذر في ترك الجماعة. نعم. المقدم: جزاكم الله خيرًا، وأحسن إليكم.","link":"https://binbaz.org.sa/fatwas/18446/حكم-الجمع-بين-الصلاتين-في-المطر","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_738/nour_73816.mp3","categories":["أحكام الجمع"]},{"id":19464,"question":"من أسئلة هذه السائلة تقول أيضًا يا سماحة الشيخ: هل يجوز لي جمع الصلاة الظهر والعصر والمغرب والعشاء مع بعض؟","title":"حكم الجمع بين الصلاتين للمرأة","answer":"الجواب: إذا كانت مريضة جاز لها، أو كانت عندها استحاضة معها الدماء تمشي بين الحيضتين المستحاضة فيشق عليها جاز لها الجمع، لكن الأفضل يكون جمع صوري تؤخر الظهر إلى آخر وقتها والعصر في أول وقتها، والمغرب في آخر وقتها والعشاء في أول وقتها، وإن صلت كل صلاة في وقتها فهو أفضل، لكن إذا دعت الحاجة إلى الجمع فلا حرج كما أفتى النبي ﷺ حمنة رضي الله عنها. نعم.","link":"https://binbaz.org.sa/fatwas/18704/حكم-الجمع-بين-الصلاتين-للمراة","audio":"https://files.zadapps.info/binbaz.org.sa/fatawa/nour_3la_aldarb/nour_939/nour_93903.mp3","categories":["أحكام الجمع"]}]
